mapper.select:
select tw.`water_type`,tw.`water_type_name`,sum(tw.`water_usage`) as `total_usage` from `treated_water_usage_hour` tw
where tw.`deleted` = 0

      and tw.`date_hour` >= #{param.period.begin}


      and tw.`date_hour` < #{param.period.end}

group by tw.`water_type` order by `total_usage` desc

select tw.`water_type`,tw.`water_type_name`,DATE_FORMAT(tw.`date_hour`, #{param.dateFormat}) as `date_hour`,sum(tw.`water_usage`) as `total_usage` from `treated_water_usage_hour` tw
where tw.`deleted` = 0

    and tw.`date_hour` >= #{param.period.begin}


    and tw.`date_hour` < #{param.period.end}

group by tw.`water_type`,DATE_FORMAT(tw.`date_hour`, #{param.dateFormat})

select tw.`water_type`,tw.`water_type_name`,DATE_FORMAT(tw.`date_hour`, #{param.dateFormat}) as `date_hour`,sum(tw.`water_usage`) as `total_usage` from `treated_water_usage_hour` tw
where tw.`deleted` = 0

    and tw.`date_hour` >= #{param.period.begin}


    and tw.`date_hour` < #{param.period.end}

group by tw.`water_type`,DATE_FORMAT(tw.`date_hour`, #{param.dateFormat})

select tw.`water_type`,tw.`water_type_name`,to_char(tw.`date_hour`, #{param.dateFormat}) as `date_hour`,sum(tw.`water_usage`) as `total_usage` from `treated_water_usage_hour` tw
where tw.`deleted` = 0

    and tw.`date_hour` >= #{param.period.begin}


    and tw.`date_hour` < #{param.period.end}

group by tw.`water_type`,to_char(tw.`date_hour`, #{param.dateFormat})

select tw.`area_name`,sum(tw.`water_usage`) as `total_usage` from `treated_water_usage_hour` tw
where tw.`deleted` = 0

    and tw.`date_hour` >= #{param.period.begin}


    and tw.`date_hour` < #{param.period.end}

group by tw.`area_name` order by `total_usage` desc
